/* eslint-disable-next-line @typescript-eslint/no-require-imports */
function applySettingsChangeForAppState(
  source: SettingSource,
  setState: (f: (prev: AppState) => AppState) => void,
): void {
  const mod = require('@thyrox/config/applySettingsChange') as {
    applySettingsChange: typeof applySettingsChangeForAppState
  }
  mod.applySettingsChange(source, setState)
}

